-- GPS field tests have their own catalog, rules, runs and evidence. They never
-- write official places, participation, routes, payments or memorial tables.
create table sskr_private.field_places (
  id text primary key check(id like 'test-%'),
  document jsonb not null check(jsonb_typeof(document)='object')
);
create table sskr_private.field_sessions (
  id uuid primary key,
  revision bigint not null default 1,
  document jsonb not null,
  updated_at timestamptz not null default now()
);
create table sskr_private.field_runs (
  id uuid primary key,
  owner_id uuid not null references auth.users(id),
  session_id uuid not null references sskr_private.field_sessions(id),
  revision bigint not null default 1,
  document jsonb not null,
  updated_at timestamptz not null default now()
);
create index field_runs_owner on sskr_private.field_runs(owner_id,updated_at desc);
create index field_runs_session on sskr_private.field_runs(session_id);
create table sskr_private.field_audit (
  id bigint generated always as identity primary key,
  actor_id uuid not null references auth.users(id),
  subject_id uuid not null,
  action text not null,
  document jsonb not null,
  created_at timestamptz not null default now()
);
create index field_audit_actor on sskr_private.field_audit(actor_id);
create index field_audit_subject on sskr_private.field_audit(subject_id,id desc);
alter table sskr_private.field_places enable row level security;
alter table sskr_private.field_sessions enable row level security;
alter table sskr_private.field_runs enable row level security;
alter table sskr_private.field_audit enable row level security;
revoke all on sskr_private.field_places,sskr_private.field_sessions,sskr_private.field_runs,sskr_private.field_audit from public,anon,authenticated;
create trigger field_audit_immutable before update or delete on sskr_private.field_audit
  for each row execute function sskr_private.reject_event_history_change();

-- Service-only BFF boundary. The caller authenticates and checks the test mode
-- on every request; this function checks ownership/operator access independently.
create function public.sskr_field_tests(p_action text,p_actor uuid,p_data jsonb default '{}',p_id uuid default null,p_revision bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare op boolean; sess sskr_private.field_sessions; rec sskr_private.field_runs; result jsonb;
begin
  if p_actor is null or not exists(select 1 from auth.users where id=p_actor and not coalesce(is_anonymous,false) and (banned_until is null or banned_until<now())) then raise exception 'FORBIDDEN'; end if;
  op:=exists(select 1 from sskr_private.event_operators where user_id=p_actor);
  if p_action='list' then
    return jsonb_build_object('operator',op,
      'places',coalesce((select jsonb_agg(document order by id) from sskr_private.field_places),'[]'::jsonb),
      'sessions',coalesce((select jsonb_agg(jsonb_build_object('id',id,'revision',revision,'document',document) order by updated_at desc) from sskr_private.field_sessions where op or document->>'enabled'='true'),'[]'::jsonb),
      'runs',coalesce((select jsonb_agg(x.doc order by x.updated_at desc) from (select updated_at,jsonb_build_object('id',id,'sessionId',session_id,'title',document#>>'{config,title}','state',document#>>'{run,state}','updatedAt',updated_at) doc from sskr_private.field_runs where owner_id=p_actor order by updated_at desc limit 50) x),'[]'::jsonb));
  end if;
  if p_action='configure' then
    if not op then raise exception 'FORBIDDEN'; end if;
    perform pg_advisory_xact_lock(hashtextextended(p_id::text,0));
    select * into sess from sskr_private.field_sessions where id=p_id for update;
    if (sess.id is null and p_revision<>0) or (sess.id is not null and sess.revision<>p_revision) or p_revision is null then raise exception 'CONFLICT'; end if;
    insert into sskr_private.field_sessions(id,document) values(p_id,p_data)
      on conflict(id) do update set document=excluded.document,revision=sskr_private.field_sessions.revision+1,updated_at=now()
      returning * into sess;
    insert into sskr_private.field_audit(actor_id,subject_id,action,document) values(p_actor,p_id,'CONFIGURE',jsonb_build_object('revision',sess.revision,'config',p_data));
    return jsonb_build_object('id',p_id,'revision',sess.revision,'document',sess.document);
  end if;
  if p_action='begin' then
    perform pg_advisory_xact_lock(hashtextextended(p_actor::text,1));
    select * into rec from sskr_private.field_runs where id=p_id;
    if rec.id is not null then
      if rec.owner_id<>p_actor then raise exception 'NOT_FOUND'; end if;
      if rec.session_id<>(p_data->>'sessionId')::uuid or rec.document->>'startId'<>p_data->>'startId' then raise exception 'CONFLICT'; end if;
    else
      select * into sess from sskr_private.field_sessions where id=(p_data->>'sessionId')::uuid for share;
      if sess.id is null or sess.document->>'enabled'<>'true' then raise exception 'DISABLED'; end if;
      if sess.revision<>(p_data->>'sessionRevision')::bigint then raise exception 'CONFLICT'; end if;
      if (select count(*) from sskr_private.field_runs where owner_id=p_actor)>=200 then raise exception 'LIMIT_REACHED'; end if;
      insert into sskr_private.field_runs(id,owner_id,session_id,document) values(p_id,p_actor,sess.id,p_data) returning * into rec;
    end if;
  elsif p_action in ('load','checkin') then
    select * into rec from sskr_private.field_runs where id=p_id and owner_id=p_actor for update;
    if rec.id is null then raise exception 'NOT_FOUND'; end if;
    if p_action='checkin' then
      select * into sess from sskr_private.field_sessions where id=rec.session_id for share;
      if sess.document->>'enabled'<>'true' then raise exception 'DISABLED'; end if;
      if p_revision is null or p_revision<>rec.revision then raise exception 'CONFLICT'; end if;
      update sskr_private.field_runs set document=p_data->'document',revision=revision+1,updated_at=now() where id=p_id returning * into rec;
      insert into sskr_private.field_audit(actor_id,subject_id,action,document) values(p_actor,p_id,'CHECKIN',p_data->'evidence');
    end if;
  else raise exception 'INVALID_INPUT'; end if;
  return jsonb_build_object('id',rec.id,'sessionId',rec.session_id,'revision',rec.revision,'document',rec.document);
end $$;
revoke all on function public.sskr_field_tests(text,uuid,jsonb,uuid,bigint) from public,anon,authenticated;
grant execute on function public.sskr_field_tests(text,uuid,jsonb,uuid,bigint) to service_role;

